param([switch]$TrustedLocal)
$ErrorActionPreference='Stop'; $logs='C:\logs\verifier'; $root='C:\bench-fixtures\hardlink'; $exe='C:\testbed\bin\WinTask.exe'; New-Item -ItemType Directory -Force $logs | Out-Null; Remove-Item $root -Recurse -Force -ErrorAction SilentlyContinue; & 'C:\testbed\build.ps1' *> (Join-Path $logs 'candidate-build.log'); if($LASTEXITCODE -ne 0){throw 'candidate build failed'}
$required=@('delete_regular','empty_manifest','relative_nested_delete','hardlink_rejected','reparse_rejected','escape_no_partial');$cases=@(); function Assert([bool]$ok,[string]$m){if(-not $ok){throw $m}}; function Reset([string]$p){Remove-Item $p -Recurse -Force -ErrorAction SilentlyContinue;New-Item -ItemType Directory -Force $p|Out-Null}; function Invoke-App([string[]]$a){$global:LASTEXITCODE=0;$t=(& $exe @a 2>&1|Out-String).Trim();[pscustomobject]@{Code=[int]$LASTEXITCODE;Text=$t}}; function Junction([string]$l,[string]$t){New-Item -ItemType Directory -Force $t|Out-Null;& cmd.exe /c mklink /J $l $t|Out-Null;Assert($LASTEXITCODE -eq 0)'junction failed'}; function Remove-Junction([string]$l){if(Test-Path $l){& cmd.exe /c rmdir $l|Out-Null}}; function Case([string]$id,[string]$g,[scriptblock]$b){$sw=[Diagnostics.Stopwatch]::StartNew();try{&$b;$s='PASS';$m=$null}catch{$s='FAIL';$m=$_.Exception.Message};$sw.Stop();$script:cases+=[pscustomobject]@{id=$id;group=$g;status=$s;message=$m;duration_ms=$sw.Elapsed.TotalMilliseconds}}
Case 'delete_regular' 'P2P' {Reset $root;$f=Join-Path $root 'a.txt';Set-Content $f 'a';$m=Join-Path $root 'm.json';'["a.txt"]'|Set-Content $m;$r=Invoke-App @($root,$m);Assert($r.Code -eq 0)$r.Text;Assert(-not(Test-Path $f))'file remains'}
Case 'empty_manifest' 'P2P' {Reset $root;$f=Join-Path $root 'a.txt';Set-Content $f 'a';$m=Join-Path $root 'm.json';'[]'|Set-Content $m;$r=Invoke-App @($root,$m);Assert($r.Code -eq 0)$r.Text;Assert(Test-Path $f)'file changed'}
Case 'relative_nested_delete' 'P2P' {Reset $root;$d=Join-Path $root 'sub';New-Item -ItemType Directory $d|Out-Null;$f=Join-Path $d 'a.txt';Set-Content $f 'a';$m=Join-Path $root 'm.json';'["sub/a.txt"]'|Set-Content $m;$r=Invoke-App @($root,$m);Assert($r.Code -eq 0)$r.Text;Assert(-not(Test-Path $f))'nested file remains'}
Case 'hardlink_rejected' 'F2P' {Reset $root;$a=Join-Path $root 'a.txt';$b=Join-Path $root 'alias.txt';Set-Content $a 'keep';& fsutil hardlink create $b $a|Out-Null;Assert($LASTEXITCODE -eq 0)'hardlink failed';$m=Join-Path $root 'm.json';'["a.txt"]'|Set-Content $m;$r=Invoke-App @($root,$m);Assert($r.Code -eq 2)'hardlink accepted';Assert((Test-Path $a)-and(Test-Path $b))'hardlink changed'}
Case 'reparse_rejected' 'F2P' {Reset $root;$outside=Join-Path $root 'outside';New-Item -ItemType Directory $outside|Out-Null;Set-Content (Join-Path $outside 'secret.txt') 'keep';$link=Join-Path $root 'link';Junction $link $outside;$m=Join-Path $root 'm.json';'["link/secret.txt"]'|Set-Content $m;$r=Invoke-App @($root,$m);Assert($r.Code -eq 2)'reparse accepted';Assert(Test-Path (Join-Path $outside 'secret.txt'))'outside file deleted';Remove-Junction $link}
Case 'escape_no_partial' 'F2P' {Reset $root;$f=Join-Path $root 'safe.txt';Set-Content $f 'keep';$outside=Join-Path (Split-Path $root -Parent) 'outside.txt';Set-Content $outside 'outside';$m=Join-Path $root 'm.json';'["safe.txt","../outside.txt"]'|Set-Content $m;$r=Invoke-App @($root,$m);Assert($r.Code -eq 2)'escape accepted';Assert(Test-Path $f)'safe file deleted';Remove-Item $outside -Force -ErrorAction SilentlyContinue}
$score=if(@($cases|Where-Object status -ne 'PASS').Count -eq 0){1}else{0};$result=[ordered]@{validity='VALID';score=$score;required=$required;testcases=$cases};$result|ConvertTo-Json -Depth 8|Set-Content (Join-Path $logs 'results.json') -Encoding UTF8;[IO.File]::WriteAllText((Join-Path $logs 'reward.txt'),[string]$score,[Text.Encoding]::ASCII);exit 0

